USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_Procurement_ReadyForProcurement_Get
 @Search NVARCHAR(200)=NULL,@RequisitionType VARCHAR(20)=NULL,@ConcernDivisionId BIGINT=NULL,@FromDate DATE=NULL,@ToDate DATE=NULL,@PageNumber INT=1,@PageSize INT=10
AS
BEGIN
 SET NOCOUNT ON;IF @PageNumber<1 SET @PageNumber=1;IF @PageSize<1 OR @PageSize>100 SET @PageSize=10;
 ;WITH ready AS(
  SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,o.ORG_UNIT_NAME,
   STRING_AGG(CONVERT(NVARCHAR(MAX),i.ITEM_NAME_SNAPSHOT),', ')AS ASSET_NAMES,
   STRING_AGG(CONVERT(NVARCHAR(MAX),REPLACE(i.REQ_TYPE,'_',' ')),', ')AS REQUISITION_TYPES,
   cd.CONCERN_DIVISION_ID,co.ORG_UNIT_NAME CONCERN_DIVISION_NAME,readyDate.READY_DATE
  FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID
  JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1
  JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.PROCUREMENT_STATUS_MASTER ps ON ps.STATUS_ID=p.CURRENT_STATUS_ID AND ps.STATUS_CODE='READY_FOR_PROCUREMENT'
  CROSS APPLY(SELECT MIN(ph.STATUS_DATE)READY_DATE FROM dbo.PROCUREMENT_STATUS_HISTORY ph JOIN dbo.PROCUREMENT_STATUS_MASTER rhs ON rhs.STATUS_ID=ph.STATUS_ID AND rhs.STATUS_CODE='READY_FOR_PROCUREMENT' WHERE ph.PROCUREMENT_ID=p.PROCUREMENT_ID HAVING COUNT(*)>0)readyDate
  OUTER APPLY(SELECT TOP(1)wr.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE wi JOIN dbo.WORKFLOW_RULE wr ON wr.WORKFLOW_RULE_ID=wi.WORKFLOW_RULE_ID WHERE wi.REQUISITION_ID=h.REQUISITION_ID ORDER BY wi.WORKFLOW_INSTANCE_ID DESC)cd
  LEFT JOIN dbo.CONCERN_DIVISION_SETUP cds ON cds.CONCERN_DIVISION_ID=cd.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT co ON co.ORG_UNIT_ID=cds.ORG_UNIT_ID
  WHERE h.IS_ACTIVE=1 AND h.CURRENT_STATUS='READY_FOR_PROCUREMENT' AND(@Search IS NULL OR h.REQUISITION_NO LIKE'%'+@Search+'%'OR i.ITEM_NAME_SNAPSHOT LIKE'%'+@Search+'%'OR o.ORG_UNIT_NAME LIKE'%'+@Search+'%')AND(@RequisitionType IS NULL OR i.REQ_TYPE=@RequisitionType)AND(@ConcernDivisionId IS NULL OR cd.CONCERN_DIVISION_ID=@ConcernDivisionId)AND(@FromDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)>=@FromDate)AND(@ToDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)<=@ToDate)
  GROUP BY h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,o.ORG_UNIT_NAME,cd.CONCERN_DIVISION_ID,co.ORG_UNIT_NAME,readyDate.READY_DATE)
 SELECT REQUISITION_ID,REQUISITION_NO,REQUESTED_DATE,ORG_UNIT_NAME,ASSET_NAMES,REQUISITION_TYPES,CONCERN_DIVISION_ID,CONCERN_DIVISION_NAME,READY_DATE FROM ready ORDER BY READY_DATE DESC OFFSET(@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
 SELECT COUNT(DISTINCT h.REQUISITION_ID)TOTAL_COUNT FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1 JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.PROCUREMENT_STATUS_MASTER ps ON ps.STATUS_ID=p.CURRENT_STATUS_ID AND ps.STATUS_CODE='READY_FOR_PROCUREMENT' OUTER APPLY(SELECT TOP(1)wr.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE wi JOIN dbo.WORKFLOW_RULE wr ON wr.WORKFLOW_RULE_ID=wi.WORKFLOW_RULE_ID WHERE wi.REQUISITION_ID=h.REQUISITION_ID ORDER BY wi.WORKFLOW_INSTANCE_ID DESC)cd WHERE h.IS_ACTIVE=1 AND h.CURRENT_STATUS='READY_FOR_PROCUREMENT'AND(@Search IS NULL OR h.REQUISITION_NO LIKE'%'+@Search+'%'OR i.ITEM_NAME_SNAPSHOT LIKE'%'+@Search+'%'OR o.ORG_UNIT_NAME LIKE'%'+@Search+'%')AND(@RequisitionType IS NULL OR i.REQ_TYPE=@RequisitionType)AND(@ConcernDivisionId IS NULL OR cd.CONCERN_DIVISION_ID=@ConcernDivisionId)AND(@FromDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)>=@FromDate)AND(@ToDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)<=@ToDate);
 SELECT s.CONCERN_DIVISION_ID,o.ORG_UNIT_NAME FROM dbo.CONCERN_DIVISION_SETUP s JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE s.IS_ACTIVE=1 ORDER BY o.ORG_UNIT_NAME;
END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Procurement_RequisitionForm_Get @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30)
AS
BEGIN
 SET NOCOUNT ON;SET XACT_ABORT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER h JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE h.REQUISITION_ID=@RequisitionId AND h.IS_ACTIVE=1 AND h.CURRENT_STATUS='READY_FOR_PROCUREMENT'AND s.STATUS_CODE='READY_FOR_PROCUREMENT')THROW 51003,'The requisition is not Ready for Procurement.',1;
 DECLARE @GeneratedOn DATETIME2(3)=SYSUTCDATETIME();
 SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.JUSTIFICATION,h.CURRENT_STATUS,o.ORG_UNIT_NAME REQUESTING_UNIT,u.DISPLAY_NAME REQUESTED_BY,u.DESIGNATION,
  cd.CONCERN_DIVISION_ID,co.ORG_UNIT_NAME CONCERN_DIVISION_NAME,@GeneratedOn GENERATED_ON,actor.DISPLAY_NAME GENERATED_BY,actorOrg.ORG_UNIT_NAME GENERATED_BY_UNIT
 FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID
 LEFT JOIN dbo.APP_USER_CACHE actor ON actor.EMPLOYEE_ID=@ActorEmployeeId LEFT JOIN dbo.ORG_UNIT actorOrg ON actorOrg.ORG_UNIT_ID=actor.ORG_UNIT_ID
 OUTER APPLY(SELECT TOP(1)wr.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE wi JOIN dbo.WORKFLOW_RULE wr ON wr.WORKFLOW_RULE_ID=wi.WORKFLOW_RULE_ID WHERE wi.REQUISITION_ID=h.REQUISITION_ID ORDER BY wi.WORKFLOW_INSTANCE_ID DESC)cd
 LEFT JOIN dbo.CONCERN_DIVISION_SETUP cds ON cds.CONCERN_DIVISION_ID=cd.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT co ON co.ORG_UNIT_ID=cds.ORG_UNIT_ID WHERE h.REQUISITION_ID=@RequisitionId;

 SELECT i.REQ_ITEM_ID,i.ITEM_NAME_SNAPSHOT ASSET_NAME,i.REQ_TYPE,i.QUANTITY,i.PURPOSE_JUSTIFICATION,i.ADDITIONAL_SPEC_REQUIREMENT,
  ri.ASSET_TAG_NO,ri.SERIAL_NO,ri.CURRENT_CONDITION,ri.ADDITIONAL_INFO,
  STUFF((SELECT'; '+s.SPEC_NAME_SNAPSHOT+': '+COALESCE(NULLIF(s.SPEC_TEXT_VALUE,''),CONVERT(NVARCHAR(100),s.SPEC_NUM_VALUE),CONVERT(NVARCHAR(30),s.SPEC_DATE_VALUE,106),CASE WHEN s.SPEC_BOOL_VALUE=1 THEN'Yes'WHEN s.SPEC_BOOL_VALUE=0 THEN'No'END,(SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),so.SELECTED_OPTION_TEXT_SNAPSHOT),', ')FROM dbo.REQUISITION_ITEM_SPEC_OPTION so WHERE so.REQ_ITEM_SPEC_ID=s.REQ_ITEM_SPEC_ID),'—')FROM dbo.REQUISITION_ITEM_SPEC s WHERE s.REQ_ITEM_ID=i.REQ_ITEM_ID ORDER BY s.DISPLAY_ORDER_SNAPSHOT FOR XML PATH(''),TYPE).value('.','NVARCHAR(MAX)'),1,2,'') SPECIFICATIONS
 FROM dbo.REQUISITION_ITEM i LEFT JOIN dbo.REQUISITION_REPLACEMENT_INFO ri ON ri.REQ_ITEM_ID=i.REQ_ITEM_ID WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1 ORDER BY i.REQ_ITEM_ID;

 SELECT ROW_NUMBER()OVER(ORDER BY wh.ACTION_DATETIME,wh.WORKFLOW_HISTORY_ID)SEQUENCE,
  CASE wh.ACTION_TYPE WHEN'SUBMIT'THEN'Requisition Submitted'WHEN'MANAGER_APPROVE'THEN'Branch/Division Manager'WHEN'PROCUREMENT_OFFICER_APPROVE'THEN'Procurement Officer'WHEN'PROCUREMENT_AUTHORITY_APPROVE'THEN'Procurement Authority'WHEN'PROCUREMENT_AUTHORITY_FORWARD'THEN'Procurement Authority'WHEN'CONCERN_VERIFY_COMPLETE'THEN'Concern Division Official'WHEN'CONCERN_FORWARD_TO_AUTHORITY'THEN'Concern Division Official'WHEN'CONCERN_AUTHORITY_APPROVE'THEN'Concern Division Authority'ELSE REPLACE(wh.FROM_STAGE,'_',' ')END STAGE_NAME,
  COALESCE(u.DISPLAY_NAME,wh.ACTION_BY_EMPLOYEE_ID)OFFICIAL_NAME,u.DESIGNATION,ou.ORG_UNIT_NAME UNIT_NAME,
  CASE wh.ACTION_TYPE WHEN'SUBMIT'THEN'Submitted'WHEN'MANAGER_APPROVE'THEN'Approved'WHEN'PROCUREMENT_OFFICER_APPROVE'THEN'Recommended'WHEN'PROCUREMENT_AUTHORITY_APPROVE'THEN'Approved'WHEN'PROCUREMENT_AUTHORITY_FORWARD'THEN'Forwarded'WHEN'CONCERN_VERIFY_COMPLETE'THEN'Recommended'WHEN'CONCERN_FORWARD_TO_AUTHORITY'THEN'Forwarded to Authority'WHEN'CONCERN_AUTHORITY_APPROVE'THEN'Approved'ELSE REPLACE(wh.ACTION_TYPE,'_',' ')END DECISION,
  wh.REMARKS,wh.ACTION_DATETIME
 FROM dbo.WORKFLOW_HISTORY wh LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=wh.ACTION_BY_EMPLOYEE_ID LEFT JOIN dbo.ORG_UNIT ou ON ou.ORG_UNIT_ID=u.ORG_UNIT_ID WHERE wh.REQUISITION_ID=@RequisitionId ORDER BY wh.ACTION_DATETIME,wh.WORKFLOW_HISTORY_ID;

 SELECT ps.STATUS_NAME CURRENT_STATUS,MIN(ph.STATUS_DATE)READY_DATE FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.PROCUREMENT_STATUS_MASTER ps ON ps.STATUS_ID=p.CURRENT_STATUS_ID JOIN dbo.PROCUREMENT_STATUS_HISTORY ph ON ph.PROCUREMENT_ID=p.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER hs ON hs.STATUS_ID=ph.STATUS_ID AND hs.STATUS_CODE='READY_FOR_PROCUREMENT' WHERE p.REQUISITION_ID=@RequisitionId GROUP BY ps.STATUS_NAME;
 INSERT dbo.AUDIT_LOG(ENTITY_NAME,ENTITY_ID,ACTION_TYPE,NEW_VALUE_JSON,ACTION_BY_EMPLOYEE_ID)VALUES('REQUISITION',@RequisitionId,'REQUISITION_FORM_GENERATED',(SELECT @GeneratedOn GeneratedOn FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@ActorEmployeeId);
END;
GO
